INSERT INTO `news` (`id`, `title`, `text`, `picture`, `category_id`, `user_id`) VALUES
(1, 'Raie vähendamine riigimetsas paneb puidutöösturid muretsema', 'Kliimaministeeriumi otsus vähendada riigimetsas raiet kümnendiku võrra mõjutab eelkõige saeveskite tööd, kuid ettevõtjate hinnangul võib kohaliku toormaterjali kättesaadavuse vähendamine tuua kaasa kogu puidusektori konkurentsivõime languse.', , 1, 1),
(2, 'Saku vabatahtlikud on nädalavahetusel reageerinud mitmekümnele väljakutsele', 'Saku vallas vabatahtlike gruppi koondunud nelikveoga autode omanikel oli nädalavahetus tihe: paari päeva jooksul käidi mitukümment teelt välja sõitnud autot teele tagasi upitamas. Pühapäeval sikutati kraavist välja ka liinibuss.', , 1, 1);
INSERT INTO `news` (`id`, `title`, `text`, `picture`, `category_id`, `user_id`) VALUES
(3, 'Detsember toidupoes: liha ja piim kallinesid veelgi', 'Möödunud aasta viimasel kuul maksis nii sea-, veise- kui ka broileriliha märksa enam kui 2024. aasta detsembris ning kallinesid ka piimatooted ja köögiviljad. Detsembris maksid kõik lihatooted rohkem kui aasta varem, näitavad konjunktuuriinstituudi värsked andmed. Kõige enam kallines kondita veiseliha: aasta eest detsembris maksis selle kilogramm 17,68 eurot, lõppenud aasta detsembris aga 22,11 eurot ehk veerandi võrra rohkem.', , 3, 1),
(4, 'Trump kutsus seadma krediitkaardi intressidele 10-protsendist ülempiiri', 'USA president Donald Trump kutsus üles kehtestama krediitkaardi intressidele üheks aastaks 10-protsendine ülempiir, et leevendada valijate muret elukalliduse pärast.\r\n\"Palun teavitage, et me ei lase enam Ameerika avalikkust petta krediitkaardifirmadel, mis nõuavad 20- ja 30-protsendiseid ja isegi kõrgemaid intressimäärasid,\" postitas Trump reedel sotsiaalmeedias, lisades, et soovib ülempiiri kehtestamist alates 20. jaanuarist.', , 2, 1);

